/**
 * Spark Playground — input data, pipeline, configuration, execution, metrics.
 *
 * Every figure here was computed by Python from the event log Spark wrote. The
 * screen's responsibility is to keep that visible: structural and timing
 * measurements are separated, the dataset sample is the real generated bytes,
 * and the three steps RepoLab adds to the repository's job are labelled as
 * RepoLab's.
 *
 * Spec: docs/design/04-playground.md
 */

"use client";

import { useCallback, useEffect, useState } from "react";

import { ProportionBar } from "@/components/charts";
import { Badge, Empty, ErrorNote, Note, Panel, Skeleton, Stat } from "@/components/ui";
import { ActivityFeed } from "@/components/activity";
import { api, ApiError, optional } from "@/lib/api";
import { useEventStream } from "@/lib/events";
import { bytes, count, ms, shortHash } from "@/lib/format";
import type { DatasetPreview, RunView } from "@/lib/types";

import { useWorkspace } from "../workspace";

/** Rows for a browser-initiated run. Smaller than the CLI default so the
 *  playground stays responsive while still producing real skew. */
const DEFAULT_ROWS = 60_000;

const PARTITION_CHOICES = [8, 50, 100, 200, 400, 800];

export default function PlaygroundPage() {
  const { job, environmentReady } = useWorkspace();
  const repoUrl = job?.repo_url;

  const [partitions, setPartitions] = useState(200);
  const [rows, setRows] = useState(DEFAULT_ROWS);
  const [preview, setPreview] = useState<DatasetPreview | null>(null);
  const [runJobId, setRunJobId] = useState<string | null>(null);
  const [run, setRun] = useState<RunView | null>(null);
  const [previous, setPrevious] = useState<RunView[]>([]);
  const [error, setError] = useState<string | null>(null);
  const [starting, setStarting] = useState(false);

  const { events, status } = useEventStream(runJobId ? api.eventsUrl(runJobId) : null);
  const running = runJobId !== null && run === null && error === null;

  // The preview is the real dataset, so its hash is the hash the run records.
  useEffect(() => {
    let cancelled = false;
    void (async () => {
      try {
        const next = await api.datasetPreview(rows);
        if (!cancelled) setPreview(next);
      } catch (cause) {
        if (!cancelled) setError(cause instanceof ApiError ? cause.message : String(cause));
      }
    })();
    return () => { cancelled = true; };
  }, [rows]);

  useEffect(() => {
    if (!repoUrl) return;
    let cancelled = false;
    void (async () => {
      const runs = await optional(api.runs(repoUrl));
      if (!cancelled && runs) setPrevious(runs);
    })();
    return () => { cancelled = true; };
  }, [repoUrl, run]);

  // Poll for the measurements once the run's job reports it is done. The run
  // row appears only after the event log has been parsed.
  useEffect(() => {
    if (!runJobId || run) return;
    let cancelled = false;

    const poll = async () => {
      const [state, measured] = await Promise.all([
        optional(api.job(runJobId)),
        optional(api.runForJob(runJobId)),
      ]);
      if (cancelled) return;
      if (measured) setRun(measured);
      else if (state?.status === "failed") setError(state.error ?? "the pipeline failed");
    };

    void poll();
    const timer = setInterval(poll, 1500);
    return () => { cancelled = true; clearInterval(timer); };
  }, [runJobId, run]);

  const start = useCallback(async () => {
    if (!repoUrl) return;
    setError(null);
    setRun(null);
    setStarting(true);
    try {
      const started = await api.startRun(repoUrl, partitions, rows);
      setRunJobId(started.job_id);
    } catch (cause) {
      setError(cause instanceof ApiError ? cause.message : String(cause));
    } finally {
      setStarting(false);
    }
  }, [repoUrl, partitions, rows]);

  const measurements = run?.measurements ?? null;

  return (
    <div className="flex flex-col gap-6">
      {environmentReady === false && (
        <Note>
          Docker is not available on this machine, so the pipeline cannot be run
          here. The panels below still describe what it would run.
        </Note>
      )}

      <Panel
        title="Input data"
        subtitle="Generated deterministically from a fixed seed, so two runs read identical bytes"
      >
        {!preview ? (
          <Skeleton rows={3} />
        ) : (
          <>
            <dl className="grid grid-cols-2 gap-4 sm:grid-cols-4">
              <Stat label="Rows" value={count(preview.total_rows)} />
              <Stat label="Distinct keys" value={count(preview.distinct_keys)} />
              <Stat
                label={`Skew on '${preview.spec.skewed_key}'`}
                value={`${(preview.spec.skew_fraction * 100).toFixed(0)}%`}
                hint={`${count(preview.spec.skewed_rows)} rows`}
              />
              <Stat label="Size" value={bytes(preview.spec.size_bytes)} />
              <Stat
                label="Dataset sha256"
                value={shortHash(preview.sha256, 16)}
                hint="The hash the run will record"
              />
            </dl>

            <div className="mt-4 overflow-x-auto">
              <table
                data-testid="dataset-sample"
                className="w-full border-collapse text-left font-mono text-xs"
              >
                <thead>
                  <tr className="border-b border-line">
                    {preview.columns.map((column) => (
                      <th key={column} className="py-1 pr-4 font-medium text-fg-secondary">
                        {column}
                      </th>
                    ))}
                  </tr>
                </thead>
                <tbody>
                  {preview.rows.map((row, index) => (
                    <tr key={index} className="border-b border-line">
                      {row.map((cell, cellIndex) => (
                        <td key={cellIndex} className="py-1 pr-4">
                          {cell}
                        </td>
                      ))}
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
            <p className="mt-2 text-xs text-fg-muted">
              The first {preview.preview_rows} rows, cut from the real generated file.
            </p>
          </>
        )}
      </Panel>

      <Panel title="Pipeline" subtitle="What runs, and which parts RepoLab adds">
        <ol className="flex flex-col gap-2">
          <PipelineStep index={1} title="Read the CSV" origin="scaffolding">
            RepoLab&apos;s driver loads the generated dataset with an explicit schema.
          </PipelineStep>
          <PipelineStep index={2} title="transform_data()" origin="repository">
            The repository&apos;s own transformation, called exactly as it defines it.
            If it cannot be imported, the run fails rather than measuring
            something else.
          </PipelineStep>
          {(run?.added_steps ?? FALLBACK_ADDED).map((step, index) => {
            const { what, why } = splitDisclosure(step);
            return (
              <PipelineStep key={index} index={3 + index} title={what} origin="repolab">
                {why}
              </PipelineStep>
            );
          })}
        </ol>
        <p className="mt-3 text-xs text-exp-fg">
          The repository&apos;s job performs no shuffle at all, so shuffle and skew
          metrics would be structurally zero. The added steps are what make the
          question measurable — and any figure below describes the
          repository&apos;s transform <em>plus</em> RepoLab&apos;s aggregation.
        </p>
      </Panel>

      <Panel title="Configuration" subtitle="One setting is yours to change; the rest are fixed">
        <div className="flex flex-col gap-4">
          <div>
            <label htmlFor="partitions" className="text-sm font-medium">
              spark.sql.shuffle.partitions
            </label>
            <div className="mt-2 flex flex-wrap items-center gap-2">
              {PARTITION_CHOICES.map((choice) => (
                <button
                  key={choice}
                  type="button"
                  onClick={() => setPartitions(choice)}
                  data-testid={`partitions-${choice}`}
                  className={`rounded border px-3 py-1 font-mono text-sm ${
                    partitions === choice
                      ? "border-brand bg-brand text-white"
                      : "border-line-strong"
                  }`}
                >
                  {choice}
                </button>
              ))}
              <input
                id="partitions"
                type="number"
                min={1}
                max={2000}
                value={partitions}
                onChange={(event) => setPartitions(Number(event.target.value))}
                className="w-24 rounded border border-line-strong px-2 py-1 font-mono text-sm"
              />
              <span className="text-xs text-fg-secondary">200 is Spark&apos;s default</span>
            </div>
          </div>

          <div>
            <label htmlFor="rows" className="text-sm font-medium">
              Dataset rows
            </label>
            <input
              id="rows"
              type="number"
              min={1000}
              max={2_000_000}
              step={10_000}
              value={rows}
              onChange={(event) => setRows(Number(event.target.value))}
              className="ml-3 w-32 rounded border border-line-strong px-2 py-1 font-mono text-sm"
            />
          </div>

          <dl className="grid grid-cols-2 gap-3 border-t border-line pt-3 sm:grid-cols-4">
            <Stat label="Master" value="local[4]" />
            <Stat label="Driver memory" value="2g" />
            <Stat
              label="Adaptive execution"
              value="disabled"
              hint="It would coalesce partitions and hide the distribution"
            />
            <Stat label="Image" value="apache/spark:3.5.1" />
          </dl>
        </div>
      </Panel>

      <Panel
        title="Execution"
        action={
          <button
            type="button"
            onClick={start}
            disabled={starting || running || !repoUrl || environmentReady === false}
            data-testid="run-pipeline"
            className="rounded bg-brand px-4 py-2 text-sm font-medium text-white disabled:opacity-50"
          >
            {running ? "Running…" : starting ? "Starting…" : "Run the pipeline"}
          </button>
        }
      >
        {error && <ErrorNote>{error}</ErrorNote>}
        {!runJobId && !error && (
          <Empty title="Not run yet">
            Running executes the repository&apos;s job on real Spark in a container
            and measures it from Spark&apos;s own event log.
          </Empty>
        )}
        {runJobId && (
          <div className="mt-2">
            <div className="mb-2 flex items-center gap-2">
              <Badge tone={run ? "good" : status === "open" ? "live" : "neutral"}>
                {run ? "measured" : "running"}
              </Badge>
              <span className="font-mono text-xs text-fg-secondary">
                {events.length} events
              </span>
            </div>
            <ActivityFeed events={events} height="h-48" />
          </div>
        )}
      </Panel>

      {measurements && run && (
        <Panel
          title="Metrics"
          subtitle="Every figure computed by Python from the event log Spark wrote"
          action={<Badge tone="good">{run.task_count} tasks measured</Badge>}
        >
          <div className="flex flex-col gap-6" data-testid="metrics">
            <div>
              <h3 className="mb-3 text-xs font-semibold uppercase tracking-wide text-brand-fg">
                Structural · repeats exactly across identical runs
              </h3>
              <dl className="grid grid-cols-2 gap-4 sm:grid-cols-4">
                <Stat label="Stages" value={count(measurements.stage_count)} />
                <Stat label="Tasks" value={count(measurements.task_count)} />
                <Stat label="Failed tasks" value={count(measurements.failed_task_count)} />
                <Stat
                  label="Shuffle partitions"
                  value={count(measurements.distribution.partitions)}
                />
                <Stat label="Shuffle read" value={bytes(measurements.shuffle_bytes_read)} />
                <Stat label="Shuffle write" value={bytes(measurements.shuffle_bytes_written)} />
                <Stat label="Memory spilled" value={bytes(measurements.memory_bytes_spilled)} />
                <Stat label="Disk spilled" value={bytes(measurements.disk_bytes_spilled)} />
                <Stat
                  label="Heaviest partition"
                  value={`${count(measurements.distribution.max_records)} records`}
                />
                <Stat
                  label="Median non-empty"
                  value={`${count(Math.round(measurements.distribution.median_records))} records`}
                />
                <Stat
                  label="Partition skew"
                  value={`${skewRatio(measurements.distribution)}×`}
                  hint="Heaviest vs median non-empty"
                />
                <Stat label="Spark" value={measurements.spark_version ?? "—"} />
              </dl>

              <div className="mt-4">
                <ProportionBar
                  part={measurements.distribution.empty_partitions}
                  whole={measurements.distribution.partitions}
                  partLabel="Empty partitions"
                  wholeLabel="Partitions that received no records at all"
                />
              </div>
            </div>

            <div>
              <h3 className="mb-3 text-xs font-semibold uppercase tracking-wide text-exp-fg">
                Timing · varies between runs
              </h3>
              <dl className="grid grid-cols-2 gap-4 sm:grid-cols-4">
                <Stat
                  label="Total runtime"
                  value={ms(measurements.total_runtime_ms)}
                  emphasis
                />
                <Stat label="Slowest task" value={ms(measurements.tasks.slowest_ms)} />
                <Stat label="Median task" value={ms(measurements.tasks.median_ms)} />
                <Stat label="Wall clock" value={`${run.wall_clock_seconds.toFixed(1)}s`} />
              </dl>
            </div>

            <div className="border-t border-line pt-4">
              <h3 className="text-xs font-semibold uppercase tracking-wide text-fg-secondary">
                Measurement source
              </h3>
              <dl className="mt-2 grid grid-cols-2 gap-4 sm:grid-cols-4">
                <Stat label="Event log sha256" value={shortHash(run.event_log_sha256, 16)} />
                <Stat label="Event log size" value={bytes(run.event_log_bytes)} />
                <Stat label="Lines parsed" value={count(measurements.event_log_lines)} />
                <Stat label="Dataset hash" value={shortHash(run.dataset_hash, 16)} />
              </dl>
            </div>
          </div>
        </Panel>
      )}

      {previous.length > 1 && (
        <Panel title="Previous runs" subtitle="Same repository, different configuration">
          <table className="w-full border-collapse text-left text-xs">
            <thead>
              <tr className="border-b border-line text-fg-secondary">
                <th className="py-1 pr-4 font-medium">partitions</th>
                <th className="py-1 pr-4 font-medium">empty</th>
                <th className="py-1 pr-4 font-medium">tasks</th>
                <th className="py-1 pr-4 font-medium">runtime</th>
                <th className="py-1 font-medium">event log</th>
              </tr>
            </thead>
            <tbody className="font-mono">
              {previous.slice(0, 8).map((entry) => (
                <tr key={entry.run_id} className="border-b border-line">
                  <td className="py-1 pr-4">{entry.configuration?.shuffle_partitions ?? "—"}</td>
                  <td className="py-1 pr-4">
                    {entry.measurements?.distribution.empty_partitions ?? "—"}
                  </td>
                  <td className="py-1 pr-4">{entry.task_count}</td>
                  <td className="py-1 pr-4">{ms(entry.total_runtime_ms)}</td>
                  <td className="py-1">{shortHash(entry.event_log_sha256)}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </Panel>
      )}
    </div>
  );
}

/** Shown before a run exists, so the pipeline panel is never empty. */
const FALLBACK_ADDED = [
  "repartition by the skewed key, added by RepoLab: it moves the real rows across the shuffle",
  "groupBy on the skewed key with count/sum/avg aggregates, added by RepoLab",
  "a join back onto the id column to re-attach the grouping key",
];

function PipelineStep({
  index,
  title,
  origin,
  children,
}: {
  index: number;
  title: string;
  origin: "repository" | "repolab" | "scaffolding";
  children: React.ReactNode;
}) {
  return (
    <li className="flex gap-3 rounded border border-line p-3">
      <span className="flex size-6 shrink-0 items-center justify-center rounded-full border border-line-strong text-xs text-fg-secondary">
        {index}
      </span>
      <div className="min-w-0">
        <p className="flex flex-wrap items-center gap-2 text-sm font-medium">
          <span className="font-mono">{title}</span>
          {origin === "repository" ? (
            <Badge tone="good">the repository&apos;s own step</Badge>
          ) : origin === "scaffolding" ? (
            <Badge>RepoLab&apos;s driver</Badge>
          ) : (
            <Badge tone="attention">added by RepoLab</Badge>
          )}
        </p>
        <p className="mt-1 text-xs text-fg-secondary">{children}</p>
      </div>
    </li>
  );
}

/**
 * Split a disclosure into what the step is and why RepoLab added it.
 *
 * The backend writes them as "<what>, added by RepoLab: <why>" — splitting on
 * the first comma instead left one step repeating its own title and another
 * with no reason at all.
 */
function splitDisclosure(step: string): { what: string; why: string } {
  const marker = ", added by RepoLab:";
  const at = step.indexOf(marker);
  if (at === -1) {
    const comma = step.indexOf(",");
    return comma === -1
      ? { what: step, why: "Added by RepoLab so the question is measurable." }
      : { what: step.slice(0, comma), why: step.slice(comma + 1).trim() };
  }
  return { what: step.slice(0, at), why: step.slice(at + marker.length).trim() };
}

function skewRatio(distribution: { max_records: number; median_records: number }): string {
  if (distribution.median_records <= 0) return "0";
  return (distribution.max_records / distribution.median_records).toFixed(1);
}
